152				if ok {
153					return user, nil
154				}
155			}
156		}
157	
158		list, err := s.ListUsers(ctx, find)
159		if err != nil {
160			return nil, err
161		}
162		if len(list) == 0 {
163			return nil, nil
164		}
165	
